const SECTIONS = [
  { id: "downtown", kicker: "Under the Lights", title: "Downtown & Signature Rinks", blurb: "The postcard rink in Red Arrow Park and an Olympic oval on the west side — start here.", schemaType: "SportsActivityLocation", list: [{"name": "Slice of Ice at Red Arrow Park", "where": "Downtown Milwaukee (Water St. & Kilbourn Ave., across from City Hall)", "badge": null, "dates": "2026–27 opening date not yet announced as of Nov 2, 2026. 2025–26 season: opened Fri Dec 19, 2025; closed Feb 19, 2026. 2024–25: opened Dec 13, 2024. 2023–24 (warm winter): opened Jan 5, 2024. County says it typically opens Thanksgiving weekend–early December and runs into February (March if weather allows).", "typical": true, "hours": "2025–26 published hours (2026–27 TBA): December Sun–Thu 11 a.m.–9 p.m., Fri–Sat 11 a.m.–11 p.m. January–February Sun 11 a.m.–6 p.m., Mon–Thu 11 a.m.–8 p.m. (rentals from 2 p.m.), Fri–Sat 11 a.m.–10 p.m. Holiday hours: Dec 24 11 a.m.–6 p.m.; Dec 25 4–11 p.m.; Dec 26–Jan 3 (incl. New Year's Eve) 10 a.m.–11 p.m.; Jan 4 10 a.m.–8 p.m.", "price": "Free admission with your own skates. 2025–26 rentals: $11 adults, $9 youth 17 and under, $5 pre-scheduled school/non-profit groups; skate helpers $1 + $5 refundable deposit or photo ID; skate sharpening $7; ADA ice sleds free (first come, first served). Opening day had free rentals 3–6 p.m. courtesy of WaterStone Bank.", "address": "920 N. Water St., Milwaukee, WI 53202", "url": "https://county.milwaukee.gov/EN/Parks/Experiences/In-the-Snow", "tip": "Weekday afternoons in January–February are quietest, but note rentals don't start until 2 p.m. Mon–Fri then; bring your own skates for a free midday skate. Watch the Milwaukee County Parks site/social for the 2026–27 opening announcement, which usually comes a week or so ahead.", "source": "https://urbanmilwaukee.com/pressrelease/milwaukee-county-parks-opens-slice-of-ice-at-red-arrow-park-for-2025-26-season/", "description": "Milwaukee County Parks' refrigerated outdoor rink is the city's signature skating spot, ringed by downtown towers and holiday lights. The warming house handles rentals and sharpening, and Biggby Coffee (which replaced the Starbucks that closed at the end of 2022) sells hot drinks steps from the ice. Because the ice is refrigerated it is the most predictable outdoor season in the region, but openings still shift with the weather; group outings (school/non-profit) book via 414-316-8393.", "lat": 43.0418, "lng": -87.9103}, {"name": "Pettit National Ice Center", "where": "West Allis / Milwaukee (next to State Fair Park)", "badge": null, "dates": "Indoor, open year-round; public skating listed for Nov 3–6, 2026 and ongoing (check calendar).", "hours": "Public skating sessions vary with training/events. Posted for early Nov 2026: Tue Nov 3 7:15–9 p.m.; Wed Nov 4 7–9 p.m.; Thu Nov 5 7:15–9 p.m.; Fri Nov 6 11:15 a.m.–1:15 p.m. and 7–10 p.m. Last admission sold 45 minutes before session end.", "price": "Adults (18–61) $10; seniors 62+ $9; teens 13–17 $9; youth 4–12 $8; ages 3 and under free (prices include 7.9% sales tax). Skate rental $5 (sizes 6T–15, hockey or figure); skate helper $5 (subject to availability); 10-packs $90 adult / $81 senior & teen / $72 youth (non-transferable). Free ice sled rentals via RampUp partnership with The Ability Center.", "address": "500 S. 84th St., Milwaukee, WI 53214", "url": "https://thepettit.com/public-skating/", "tip": "Friday 7–10 p.m. is the long session; weekday 7 p.m. sessions are shorter and calmer. Check thepettit.com/public-skating before you go because oval time flexes around competitions.", "source": "https://thepettit.com/public-skating/", "description": "The U.S. Olympic speedskating training site offers public skating on its 400-meter Olympic Oval, the same ice elite skaters train on; the two international-size hockey rinks are used for hockey, figure skating and lessons rather than general public sessions. Public skates are mostly weeknight evenings plus some daytime and Friday-night sessions. No free-admission days are currently published; children 3 and under are always free.", "lat": 43.0247, "lng": -88.0176}, {"name": "Deer District / Fiserv Forum Plaza — no public ice rink", "where": "Deer District, Downtown", "badge": null, "dates": "No skating rink announced for winter 2026–27.", "typical": true, "address": "1111 Vel R. Phillips Ave., Milwaukee, WI 53203", "url": "https://www.deerdistrict.com/events", "tip": "Pair a Bucks or Admirals game with a skate at Red Arrow Park; on game nights the rink's Fri–Sat late hours (to 10–11 p.m. in past seasons) line up with post-game timing.", "source": "https://www.deerdistrict.com/", "description": "Despite frequent questions, there is no ice skating rink in the Deer District or on the Fiserv Forum plaza; the plaza's winter programming is a holiday market (search listings reference a second-annual Deer District Holiday Market in late Nov–early Dec 2026) rather than ice. The nearest public ice is Slice of Ice at Red Arrow Park, about a 10-minute walk east.", "lat": 43.0451, "lng": -87.9172}, {"name": "Dinky Rink at Milwaukee Public Market — not announced for 2026–27", "where": "Third Ward", "badge": null, "dates": "Operated in winter 2024 as a free, registration-only mini rink (holds ~8 skaters). Nothing posted for 2026–27 as of Nov 2, 2026; Public Market winter events listed are Small Business Saturday (Nov 28), Holiday Window Display (Dec 1–Jan 31) and Santa Cavalcade (Dec 5).", "typical": true, "hours": "TBA / not announced", "price": "Free with registration when it operated (2024)", "address": "400 N. Water St., Milwaukee, WI 53202", "url": "https://milwaukeepublicmarket.org/event/upcoming-events", "tip": "Call the Market at 414-336-1111 or check milwaukeepublicmarket.org/event/upcoming-events for any winter 2026–27 rink announcement.", "source": "https://milwaukeepublicmarket.org/", "description": "The Public Market's tiny 'Dinky Rink' was a novelty pop-up subject to ice and weather conditions; it required free online registration and capped skaters at eight. Treat it as a maybe, not a plan, until the Market posts it.", "lat": 43.0346, "lng": -87.9085}] },
  { id: "county-parks", kicker: "Milwaukee County Parks", title: "County Park Rinks & Wilson Park", blurb: "The county's indoor rec-center rink plus the outdoor rinks it floods when the cold cooperates.", schemaType: "SportsActivityLocation", list: [{"name": "Wilson Ice Arena (Wilson Park Recreation Center)", "where": "South Side Milwaukee", "badge": null, "dates": "Indoor NHL-size rink, open year-round.", "hours": "Public skate weekday afternoons and Saturday: county page lists Mon–Fri 11 a.m.–3 p.m.; a Sep 2026 guide lists noon–3 p.m. Mon–Fri; Saturday 2:30–4:30 p.m. Times change seasonally (extended during winter break) — check the county calendar.", "price": "Adults $6.75; juniors and seniors $5; skate rental $3.75; group rates available; free adaptive ice sleds during public skate (per Sep 2026 guide). Phone (414) 281-6289.", "address": "4001 S. 20th St., Milwaukee, WI 53221", "url": "https://county.milwaukee.gov/EN/Parks/Explore/Community-Centers/Wilson-Ice-Arena", "tip": "Saturday's 2:30–4:30 session is the only weekend public skate, so arrive early for rentals; weekday noon sessions are nearly empty outside school breaks.", "source": "https://www.northshorefamilyadventures.com/winter-guides/milwaukee-ice-rinks-and-ice-skating", "description": "Milwaukee County Parks' only indoor rink, Wilson is the dependable, cheap option when outdoor ice is slush. Expect a quieter, local crowd at midday sessions; rink rentals, birthday parties and periodic Glow Skate nights are offered. It is the county's hub for skating lessons and youth hockey as well.", "lat": 42.9665, "lng": -87.9428}, {"name": "Humboldt Park Lagoon", "where": "Bay View", "badge": null, "dates": "Natural ice, weather dependent; opens only when county measures 6+ inches of ice. 2026–27 TBA.", "typical": true, "hours": "When officially open: 9 a.m.–10 p.m. (lights on until 10 p.m.)", "price": "Free; no rentals, bring your own skates", "address": "3000 S. Howell Ave., Milwaukee, WI 53207", "url": "https://humboldtparkmilwaukee.org/park-amenities/ice-skating", "tip": "Check humboldtparkmilwaukee.org and look for the 'open' signage at the lagoon; in warm winters this rink may open for only a handful of days.", "source": "https://mkecoparks.helpscoutdocs.com/article/253-where-can-i-go-ice-skating-in-the-parks", "description": "Volunteers from Humboldt Park Friends' 'Bay View Ice Skaters' committee clear snow and flood the lagoon ice with the Friends' own snow blowers once Milwaukee County Parks certifies thickness. The Friends post an ice-condition rating (Perfect to Melt) when the county supplies data, but the on-site lagoon postings are the final word. Phone (414) 482-4270.", "lat": 42.996, "lng": -87.906}, {"name": "Lake Park Ice Rink", "where": "East Side (Upper East Side bluff)", "badge": null, "dates": "Weather dependent land rink; no fixed schedule. 2026–27 TBA.", "typical": true, "hours": "Opens only when weather and ice allow; call for status", "price": "Free; bring your own skates", "address": "2975 N. Lake Park Rd., Milwaukee, WI 53211", "url": "https://lakeparkfriends.org/visit", "tip": "Call 414-962-1680 before heading over; combine with a walk to the lighthouse and the lakefront overlook.", "source": "https://mkecoparks.helpscoutdocs.com/article/253-where-can-i-go-ice-skating-in-the-parks", "description": "Lake Park Friends maintains a flooded land rink in the Olmsted-designed park near the North Point Lighthouse. It is listed on Milwaukee County's official outdoor-skating roster as a Friends-run rink, and the group confirms status by phone and Facebook rather than a live web page.", "lat": 43.067, "lng": -87.872}, {"name": "The Rink at Center Street Park (WaterStone Bank Ice Rink)", "where": "Sherman Park / Washington Heights", "badge": null, "dates": "Weather dependent land rink. Closed for 2025–26 as of March 1, 2026; 2026–27 TBA.", "typical": true, "hours": "Check the Friends' Facebook page for openings", "price": "Free; free loaner skates first come, first served (per Jan 2026 Milwaukee Magazine)", "address": "6420 W. Clarke St., Milwaukee, WI 53210", "url": "https://www.centerstreetpark.org/ice-rink", "tip": "Loaner skates are limited in size range; bring your own if you have them and leave the loaners for first-timers.", "source": "https://www.milwaukeemag.com/ice-skating-milwaukee/", "description": "Friends of Center Street Park and the volunteer 'Center Street Hosers' build and maintain this community land rink each winter, making it one of the few free outdoor rinks with loaner skates. The county lists it among its third-party-maintained rinks; conditions are announced on Facebook. Phone (414) 342-0215.", "lat": 43.062, "lng": -87.995}, {"name": "Washington Park Lagoon", "where": "Washington Park (West Side)", "badge": null, "dates": "Natural lagoon ice; opens only at 6+ inches thickness. 2026–27 TBA.", "typical": true, "hours": "Daylight/when posted open; confirm with Urban Ecology Center", "price": "Free; bring your own skates", "address": "1859 N. 40th St., Milwaukee, WI 53208", "url": "https://www.urbanecologycenter.org/branches/washington-park", "tip": "Call the Urban Ecology Center before you go; its calendar lists winter programs at the branch and staff can confirm whether the lagoon is open.", "source": "https://mkecoparks.helpscoutdocs.com/article/253-where-can-i-go-ice-skating-in-the-parks", "description": "Maintained by the Urban Ecology Center's Washington Park branch, this lagoon rink appears on Milwaukee County Parks' official list of community-maintained outdoor rinks. The UEC branch (414-344-5460) is the contact for conditions; no status web page is published.", "lat": 43.053, "lng": -87.964}, {"name": "Alyson Dudek International Ice Center at Hales Corners Park", "where": "Hales Corners", "badge": null, "dates": "Temporary rink installed each winter, weather permitting; Friends say skating 'will return later this year' but no 2026–27 date.", "typical": true, "hours": "Not published; check Friends of Hales Corners Park & Pool", "price": "Free; bring your own skates", "address": "5765 S. New Berlin Rd., Hales Corners, WI 53130", "url": "https://www.halescornerspark.com/ice-rink", "tip": "The Friends point skaters to Play It Again Sports at 74th & Edgerton (Greenfield) for buying and sharpening skates.", "source": "https://www.halescornerspark.com/ice-rink", "description": "Named for the Hales Corners native and Olympic short-track medalist, this is a volunteer-built temporary rink run by the Friends of Hales Corners Park & Pool and listed on the county's outdoor-rink roster. Park in the lot on S. New Berlin Rd. north of the pool house (not in front of the pool building). Contact 414-418-8299.", "lat": 42.943, "lng": -88.053}, {"name": "Scout Lake Park", "where": "Greendale", "badge": null, "dates": "Natural lake ice, volunteer maintained; 6-inch rule applies. 2026–27 TBA.", "typical": true, "hours": "Daylight, when posted open", "price": "Free; bring your own skates", "address": "5902 W. Loomis Rd., Greendale, WI 53129", "url": "https://county.milwaukee.gov/EN/Parks/Experiences/In-the-Snow", "tip": "Because there is no web status page, this is a go-if-you're-nearby option after a sustained cold snap rather than a destination.", "source": "https://mkecoparks.helpscoutdocs.com/article/253-where-can-i-go-ice-skating-in-the-parks", "description": "Scout Lake is on Milwaukee County Parks' official list of volunteer-maintained skating sites, with no rentals or warming house. Call (414) 425-7303 (county listing) to ask about conditions; heed 'Thin Ice' signs."}, {"name": "Sheridan Park Lagoon", "where": "Cudahy (lakefront)", "badge": null, "dates": "Natural lagoon ice, volunteer maintained; 2026–27 TBA.", "typical": true, "hours": "Daylight, when posted open", "price": "Free; bring your own skates", "address": "4800 S. Lake Dr., Cudahy, WI 53110", "url": "https://county.milwaukee.gov/EN/Parks/Experiences/In-the-Snow", "tip": "Lake-effect wind makes this one feel colder than inland rinks; dress accordingly.", "source": "https://mkecoparks.helpscoutdocs.com/article/253-where-can-i-go-ice-skating-in-the-parks", "description": "The Sheridan Park lagoon is the southernmost site on Milwaukee County Parks' outdoor-rink list, maintained by volunteers once the county confirms 6 inches of ice. No rentals, warming house or online status; county listing phone (414) 762-1550."}] },
  { id: "suburbs", kicker: "Around the Metro", title: "Suburban & Municipal Rinks", blurb: "Arenas and town-square rinks from Mequon to Oak Creek to Waukesha — many with cheaper public skate sessions than downtown.", schemaType: "SportsActivityLocation", list: [{"name": "Eble Park Ice Arena", "where": "Brookfield (Waukesha County Parks)", "badge": null, "dates": "Indoor, year-round; public skating posted for Nov 3–11, 2026 and ongoing.", "hours": "Public Ice Skating typically weekdays noon–1:30 p.m.; Adult/Senior Skate (18+) Tue & Thu 10:30 a.m.–noon in early Nov 2026; weekend and Glow Skate sessions vary — see county calendar.", "price": "$7 per skater; $6 seniors 60+ and active military; skate rental $3; groups of 10+ $5/person (book a week ahead via ebleicearena@waukeshacounty.gov); 10-pack $54 / $45 (good at Eble and Naga-Waukee). Glow Skate $12 including rental, advance tickets required at wauk.co/iceevents. Pay at the concession stand; spectators free; no skate aids provided.", "address": "19400 W. Bluemound Rd., Brookfield, WI 53045", "url": "https://waukeshacounty.gov/parks-and-land-use/parks-and-recreation/ice-arenas/eble-park-ice-arena/public-skating", "tip": "Rentals are first come, first served with no skate aids, so bring a helmet for small kids and consider the adult/senior morning session if you want open ice.", "source": "https://waukeshacounty.gov/parks-and-land-use/parks-and-recreation/ice-arenas/eble-park-ice-arena/public-skating", "description": "Waukesha County's NHL-regulation indoor rink just west of the Milwaukee County line is the most affordable indoor public skate in the metro. Sessions are short (90 minutes) and midday, so plan around them; Glow Skates sell out.", "lat": 43.0362, "lng": -88.1537}, {"name": "Naga-Waukee Park Ice Arena", "where": "Delafield (Waukesha County Parks)", "badge": null, "dates": "Indoor Olympic-size sheet, year-round; public skating posted Nov 3–11, 2026.", "hours": "Public Ice Skating weekdays noon–1:30 p.m.; Sun Nov 8 2–3:30 p.m.; Adult/Senior Skate (40+) select weekday mornings 10:30 a.m.–noon.", "price": "$7 per skater; $6 seniors 60+ and active military; rental $3 (youth 7–adult 15); 10-pack $54 / $45; group rental 8+ $1/pair; skate sharpening $7 regular, $10 new/never-sharpened. No skate aids.", "address": "2699 Golf Rd., Delafield, WI 53018", "url": "https://waukeshacounty.gov/parks-and-land-use/parks-and-recreation/ice-arenas/naga-waukee-park-ice-arena/public-skating", "tip": "The $7 sharpening here is one of the cheaper options west of Milwaukee; drop skates during a public session.", "source": "https://waukeshacounty.gov/parks-and-land-use/parks-and-recreation/ice-arenas/naga-waukee-park-ice-arena/public-skating", "description": "Naga-Waukee is the sister rink to Eble with identical pricing and a shared 10-pack pass, plus an on-site sharpening service. It sits in Naga-Waukee Park near the golf course and is a reasonable stop for Lake Country families.", "lat": 43.0486, "lng": -88.36}, {"name": "Ozaukee Ice Center", "where": "Mequon", "badge": null, "dates": "Indoor; public skating mostly Sundays during the hockey season. 2026–27 times not published online — call.", "typical": true, "hours": "Public skate mostly Sundays; call 262-375-6851 for current times", "price": "2025–26 season: $6 admission, $3 skate rental; 2026–27 TBA", "address": "5505 W. Pioneer Rd., Mequon, WI 53097", "url": "https://www.northshorefamilyadventures.com/seasonal-guides/skating", "tip": "Rentals are limited; bring your own skates if you have them.", "source": "https://www.northshorefamilyadventures.com/seasonal-guides/skating", "description": "The North Shore's indoor rink is primarily a youth-hockey and figure-skating facility, with limited public skating usually on Sunday afternoons. Its website was unreachable at verification time, so phone confirmation is required.", "lat": 43.2126, "lng": -87.9793}, {"name": "Dan Jansen Family Fest Ice Rink at Konkel Park", "where": "Greenfield", "badge": null, "dates": "Natural outdoor ice on a 'Mother Nature' schedule; city page says 'closed for the 2025–2026 season'; 2026–27 TBA.", "typical": true, "hours": "2025–26 (per Jan 2026 Milwaukee Magazine): Mon–Thu 4–8 p.m., Fri 4–9 p.m., Sat–Sun noon–9 p.m., weather permitting. Call the 24-hour line 414-297-9008 for delays/closures.", "price": "Free admission; free skate rentals and free skate trainers, first come, first served (limited sizes)", "address": "5151 W. Layton Ave., Greenfield, WI 53220", "url": "https://www.ci.greenfield.wi.us/862/Ice-Skating", "tip": "Call the hotline first and bring your own skates for guaranteed sizing; the free loaners run out at popular sizes on weekends.", "source": "https://www.ci.greenfield.wi.us/862/Ice-Skating", "description": "Greenfield's rink, named for the West Allis-born Olympic champion, is the best free package in the suburbs: no admission, free loaner skates and trainers, and a warming area with concessions during operating hours. It is natural ice, so it can close for days after a thaw.", "lat": 42.9594, "lng": -87.992}, {"name": "Fox Point Ice Rink at Longacre Park", "where": "Fox Point (North Shore)", "badge": null, "dates": "Open ~late December–February, weather permitting. 2025–26 warming house closed Feb 10, 2026; 2026–27 TBA.", "typical": true, "hours": "Mon–Fri 3:30–9 p.m.; Sat 10 a.m.–9 p.m.; Sun noon–9 p.m. (village-posted hours)", "price": "Free; no rentals", "address": "7343 N. Longacre Rd., Fox Point, WI 53217", "url": "https://www.villageoffoxpoint.com/377/Ice-Rink", "tip": "Evening hours to 9 p.m. with lights make this a good after-work skate; sign up for village alerts since the season can end abruptly in a warm February.", "source": "https://www.villageoffoxpoint.com/377/Ice-Rink", "description": "The village floods and lights a rink at Longacre Park with a warming house/pavilion; hockey is restricted to the designated west-side area. The village posts closures and asks skaters to sign up for notifications. Village Hall 414-351-8900.", "lat": 43.158, "lng": -87.902}, {"name": "Klode Park Ice Rink (and Cahill Park)", "where": "Whitefish Bay", "badge": null, "dates": "Weather dependent; most recent season ran sunrise–9 p.m. when conditions allowed. 2026–27 TBA. Note: the Village Board approved a $1.5M Klode Park Warming House reconstruction on Apr 20, 2026 (design in 2026, construction in 2027).", "typical": true, "hours": "Sunrise–9 p.m. daily when open (2025–26)", "price": "Free; no rentals, bring your own skates", "address": "5960 N. Lake Dr., Whitefish Bay, WI 53217", "url": "https://www.wfbvillage.gov/458/Project-Updates-Klode-Park-Warming-House", "tip": "Lake winds make Klode bitterly cold on clear nights; Cahill is more sheltered when it is open.", "source": "https://www.northshorefamilyadventures.com/winter-guides/milwaukee-ice-rinks-and-ice-skating", "description": "Whitefish Bay's lakefront rink on the bluff at Klode Park is a village-maintained natural rink; Cahill Park has also hosted a free village rink with a warming house in past seasons. With the warming house rebuild scheduled for 2027, confirm with the village (414-962-6690) how the 2026–27 season will operate.", "lat": 43.1278, "lng": -87.899}, {"name": "Brown Deer Community Square Ice Rink", "where": "Brown Deer", "badge": null, "dates": "2025–26: opened late November in an enclosed tent structure. 2026–27 TBA (village page not reachable at verification).", "typical": true, "hours": "Not published online; call Brown Deer Park & Rec 414-351-3070", "price": "2025–26: $7 adults, $5 children; limited free youth loaner skates first come, first served; skating aids on request", "address": "8705 N. Deerwood Dr., Brown Deer, WI 53223", "url": "https://www.browndeerwi.org/195/Parks-Recreation", "tip": "The tent makes this a good fallback on snowy days when open-air rinks are unskatable until volunteers clear them.", "source": "https://www.northshorefamilyadventures.com/seasonal-guides/skating", "description": "Brown Deer runs a covered, tent-enclosed rink at Community Square Park, which shields the ice from sun and snow and gives it a longer, more reliable season than open-air natural rinks. It is one of the few suburban rinks charging admission, and one of the few offering skating aids."}, {"name": "Lake Bluff Ice Rink", "where": "Shorewood", "badge": null, "dates": "Volunteer-run natural rink, weather dependent; 2026–27 TBA.", "typical": true, "hours": "Lighted for evening skating; daily status posted on Facebook via green/red flag system", "price": "Free; skates to borrow or rent on site when the warming house is open (per Jan 2026 Milwaukee Magazine)", "address": "1600 E. Lake Bluff Blvd., Shorewood, WI 53211", "url": "https://www.milwaukeemag.com/ice-skating-milwaukee/", "tip": "Follow the Lake Bluff Ice Rink Facebook page; a green flag means open.", "source": "https://www.milwaukeemag.com/ice-skating-milwaukee/", "description": "Volunteer 'Ice Captains' maintain this neighborhood rink behind Lake Bluff Elementary and open a warming house when the rink is operating. The 'Shorewood Chill' winter festival takes place here in early February.", "lat": 43.093, "lng": -87.879}, {"name": "Mee-Kwon Park Pond", "where": "Mequon (Ozaukee County Parks)", "badge": null, "dates": "Natural pond ice, weather dependent; 2026–27 TBA.", "typical": true, "hours": "Daytime only; no skating after dark; warming house open during skate hours", "price": "Free; bring your own skates", "address": "6333 W. Boniwell Rd., Mequon, WI 53097", "url": "https://www.northshorefamilyadventures.com/seasonal-guides/skating", "tip": "Pair with the park's sledding hill for a full winter afternoon.", "source": "https://www.northshorefamilyadventures.com/seasonal-guides/skating", "description": "Ozaukee County's Mee-Kwon Park offers natural pond skating with a warming house during skate hours. Like all pond rinks it is strictly daylight and strictly weather dependent."}, {"name": "Howard G. Mullett Ice Center", "where": "Hartland (Arrowhead campus)", "badge": null, "dates": "Indoor; public skate weekly, with extra sessions over winter break. 2026–27 schedule on the online calendar.", "typical": true, "hours": "See calendar at mulletticecenter.finnlyconnect.com/schedule/702", "price": "$8 adults; $7 youth and seniors; $5 skate rentals (currently posted)", "address": "700 North Ave., Hartland, WI 53029", "url": "http://www.mulletticecenter.com/article-26-public-skate-hours.html", "tip": "Winter-break (late Dec) sessions are added each year; check the month view of the calendar.", "source": "http://www.mulletticecenter.com/article-26-public-skate-hours.html", "description": "Lake Country's indoor rink posts weekly public skate sessions, party packages and skate sharpening, and runs Learn to Skate classes in January. Phone 262-369-3600."}, {"name": "Lowell Park & Buchner Park rinks (City of Waukesha)", "where": "Waukesha", "badge": null, "dates": "Weather permitting; 2025–26 both closed mid-February 2026. 2026–27 TBA.", "typical": true, "hours": "Unsupervised, open all day when flooded; Parks Information Line 262-522-9356", "price": "Free; no rentals", "address": "Lowell Park, 2201 Michigan Ave.; Buchner Park, 223 Oakland Ave., Waukesha, WI", "url": "https://lakecountryfamilyfun.com/ice-skating-rinks/", "tip": "Lowell's shelter and sled hill make it the better family pick of the two.", "source": "https://lakecountryfamilyfun.com/ice-skating-rinks/", "description": "The City of Waukesha floods unsupervised outdoor rinks at Lowell Park (next to a warming shelter and sledding hill) and Buchner Park. Status is given on the parks info line."}, {"name": "Not verified for 2026–27: Wauwatosa (Hart Park), West Allis, Franklin, Oak Creek/Drexel Town Square, Cedarburg, Kern Center", "where": "Various", "badge": null, "dates": "No official public-skating rink could be verified for 2026–27 at any of these.", "typical": true, "url": "https://wauwatosa.gov/departments/parks/hart-park/", "tip": "If you hear of a rink in one of these communities, confirm it with the municipality before driving over.", "source": "https://www.northshorefamilyadventures.com/winter-guides/milwaukee-ice-rinks-and-ice-skating", "description": "Wauwatosa's Hart Park page lists curling (Wauwatosa Curling Club) but no ice rink; the West Allis, Franklin, Oak Creek and Cedarburg municipal sites list no outdoor rink or Drexel Town Square rink; and a Sep 2026 guide reports MSOE's Kern Center no longer runs a dependable public skate schedule. Riverwest People's Ice Rink (3129 N. Bremen St.) is an informal volunteer rink announced only on Facebook."}] },
  { id: "lessons-curling", kicker: "Learn & Play", title: "Lessons, Hockey & Curling", blurb: "Learn-to-skate programs for kids and adults, open hockey and the clubs where you can try curling.", schemaType: "SportsActivityLocation", list: [{"name": "Pettit Skating School (Learn to Skate USA)", "where": "Pettit National Ice Center, West Allis", "badge": null, "dates": "Session 2 (Fall) 2026: registration opened Oct 12; classes start as early as Nov 3, 2026. Winter sessions follow.", "hours": "Varies by class; see thepettit.com", "price": "$99 per session for Free Skate, Youth, Teen/Adult, Hockey and Speed Skating learn-to-skate tracks; Hockey Tots (ages 4–5) and Hockey Skills (ages 6–12) also offered", "address": "500 S. 84th St., Milwaukee, WI 53214", "url": "https://thepettit.com/", "tip": "Sessions fill fast after registration opens; teens and adults get their own track so you are not in a class of 5-year-olds.", "source": "https://thepettit.com/", "description": "The Pettit runs the region's largest Learn to Skate USA program with tracks for toddlers through adults, plus hockey and speed-skating intros. The Wisconsin Figure Skating Club (wifsc.com) is based here for skaters advancing beyond basic skills.", "lat": 43.0247, "lng": -88.0176}, {"name": "Eble & Naga-Waukee Learn to Skate / Adult Intro Class", "where": "Brookfield & Delafield", "badge": null, "dates": "'Introduction to Ice Skating for Adults & Seniors' at Eble: Tuesdays Nov 10–Dec 8, 2026 (via SDMF Community Ed & Recreation); a Jan 6–Feb 3, 2026 session ran last winter. Youth Learn to Skate via Waukesha County Parks.", "hours": "Tuesday class; times on registration page", "price": "Adult intro: fee not published online; skate rental included at no extra charge", "address": "19400 W. Bluemound Rd., Brookfield, WI 53045", "url": "https://www.active.com/brookfield-wi/skating/ice-skating-classes/introduction-to-ice-skating-for-adults-and-seniors-2026-109816779", "tip": "Adults nervous about crowds should pair the class with the weekday-morning adult skate at Eble.", "source": "https://www.active.com/brookfield-wi/skating/ice-skating-classes/introduction-to-ice-skating-for-adults-and-seniors-2026-109816779", "description": "Waukesha County's two arenas run Learn to Skate programs and partner with community-ed districts for adult beginner classes taught by Eble staff. Adult/Senior public skate sessions (18+ at Eble, 40+ at Naga-Waukee) give beginners quieter practice ice.", "lat": 43.0362, "lng": -88.1537}, {"name": "Wilson Ice Arena lessons (Milwaukee County Parks)", "where": "South Side Milwaukee", "badge": null, "dates": "Year-round; session dates posted by Milwaukee County Parks", "typical": true, "hours": "See county registration", "price": "Not published at verification; call (414) 281-6289", "address": "4001 S. 20th St., Milwaukee, WI 53221", "url": "https://county.milwaukee.gov/EN/Parks/Explore/Community-Centers/Wilson-Ice-Arena", "tip": "Ask about discounted group rates if you are bringing a scout troop or class.", "source": "https://www.northshorefamilyadventures.com/winter-guides/milwaukee-ice-rinks-and-ice-skating", "description": "The county's indoor arena hosts group skating lessons and youth hockey programs at the lowest price point in the city. Details are on the county Wilson Ice Arena page (which blocked automated verification), so confirm by phone.", "lat": 42.9665, "lng": -87.9428}, {"name": "Milwaukee Curling Club — Learn to Curl", "where": "Cedarburg (Ozaukee County Fairgrounds)", "badge": null, "dates": "Fall 2026 Learn to Curl sessions: Fri Oct 2 6–9 p.m., Sat Oct 3 3–6 p.m., Sun Oct 4 noon–3 p.m. (Eventbrite). Additional sessions and a Sunday-evening New Member league run through the season.", "hours": "Leagues daily; Learn to Curl by scheduled session", "price": "Learn to Curl $40 + Eventbrite fee (1 hour instruction, 1 hour 4-v-4 game, pizza/soda/beer after)", "address": "W67 N890 Washington Ave., Cedarburg, WI 53012", "url": "http://milwaukeecurlingclub.com/", "tip": "The October sessions sell out quickly; email info@milwaukeecurlingclub.com to be notified of added dates after the Olympic bump in interest.", "source": "http://milwaukeecurlingclub.com/", "description": "Founded in 1845, the Milwaukee Curling Club bills itself as the oldest continuously operating curling club in the U.S. and runs a packed league schedule at its dedicated sheets on the Ozaukee County Fairgrounds. Learn-to-Curl nights are the entry point; corporate and group outings are also offered (corporateevents@milwaukeecurlingclub.com).", "lat": 43.299, "lng": -87.988}, {"name": "Wauwatosa Curling Club — Try Curling", "where": "Hart Park, Wauwatosa", "badge": null, "dates": "'Try Curling' open-to-the-public sessions on multiple dates through the season; Adaptive Open Bonspiel Jan 23–24, 2027; Valentine Open Feb 12–14, 2027", "hours": "By event; volunteer-run, voicemail 414-453-2875 not monitored daily — email", "price": "Not published; inquire via the club's Try Curling email", "address": "7300 W. Chestnut St., Wauwatosa, WI 53213 (Muellner Building)", "url": "https://www.wauwatosacurlingclub.com/", "tip": "This is the closest curling option to downtown Milwaukee (about 15 minutes).", "source": "https://www.wauwatosacurlingclub.com/", "description": "In the Muellner Building at Hart Park since 1941, the Wauwatosa Curling Club shares its home with the Tosa Senior Center and offers leagues for all levels, public Try Curling events, and corporate/group outings. Its January Adaptive Open Bonspiel is a notable wheelchair/adaptive curling event.", "lat": 43.049, "lng": -88.008}, {"name": "Pick-Up Hockey / Stickhandling at the Pettit", "where": "Pettit National Ice Center", "badge": null, "dates": "Weekly sessions (e.g., Mon Nov 2, 2026, noon–1:30 p.m.)", "hours": "Midday weekday sessions; see Pettit calendar", "price": "See Pettit calendar; limited to first 24 participants, first come first served", "address": "500 S. 84th St., Milwaukee, WI 53214", "url": "https://thepettit.com/", "tip": "Arrive 30 minutes early for the 24-skater cap; full gear is required.", "source": "https://thepettit.com/", "description": "The Pettit runs drop-in stickhandling/pick-up hockey sessions capped at 24 skaters, in addition to youth hockey programming. Adult league play in the metro is organized through the Pettit, Eble/Naga-Waukee contracted ice and private rinks such as The Ponds of Brookfield; check each rink's schedule for open hockey.", "lat": 43.0247, "lng": -88.0176}, {"name": "Adaptive & sled skating (free ice sleds)", "where": "Pettit, Red Arrow Park, Wilson Ice Arena", "badge": null, "dates": "Pettit year-round; Red Arrow during Slice of Ice season; Wilson during public skate", "hours": "During public skating sessions", "price": "Free ice sled rentals at all three, first come, first served", "address": "500 S. 84th St.; 920 N. Water St.; 4001 S. 20th St., Milwaukee", "url": "https://thepettit.com/public-skating/", "tip": "Sleds are limited; arrive at session start and ask at the rental window.", "source": "https://thepettit.com/public-skating/", "description": "The Pettit is a RampUp site with The Ability Center, providing free ice sleds during public skating; Milwaukee County Parks offers free ADA ice sleds at Slice of Ice and free adaptive sleds at Wilson Ice Arena. Skate helpers ($1 at Red Arrow, $5 at the Pettit) assist beginners and skaters with balance needs. The Wauwatosa Curling Club hosts an Adaptive Open Bonspiel each January.", "lat": 43.0247, "lng": -88.0176}] },
  { id: "tips", kicker: "Before You Go", title: "Skating Tips & Where to Warm Up", blurb: "Rentals, sharpening, what to wear and the best times to avoid a crowded sheet of ice.", schemaType: "Thing", list: [{"name": "What to wear", "where": "All rinks", "badge": "Season-long", "dates": "Season-long", "url": "https://county.milwaukee.gov/EN/Parks/Experiences/In-the-Snow", "tip": "Rental skates run cold; bring hand warmers to tuck in boots between laps.", "source": "https://lakecountryfamilyfun.com/ice-skating-rinks/", "description": "Thin, warm socks (not thick ones, which cramp the boot), gloves or mittens, and layers you can shed; outdoor rinks like Klode and Sheridan Park sit in lake wind and feel 10 degrees colder than downtown. Helmets are recommended for kids and beginners and encouraged by municipal rinks such as Delafield's."}, {"name": "Skate sharpening", "where": "Milwaukee & suburbs", "badge": "Season-long", "dates": "Season-long", "hours": "During rink hours / store hours", "price": "Slice of Ice warming house $7 (2025–26); Naga-Waukee $7 regular, $10 new/never-sharpened; Play It Again Sports Greenfield offers sharpening (price not posted); Mullett Ice Center offers sharpening", "address": "Red Arrow Park warming house; Naga-Waukee Ice Arena; Play It Again Sports, 74th & Edgerton, Greenfield; Mullett Ice Center, Hartland", "url": "https://waukeshacounty.gov/parks-and-land-use/parks-and-recreation/ice-arenas/naga-waukee-park-ice-arena/public-skating", "tip": "New skates need a first sharpening before use; expect a higher price for that initial grind.", "source": "https://www.halescornerspark.com/ice-rink", "description": "You do not need a pro shop: the Slice of Ice warming house and Waukesha County's Naga-Waukee arena both sharpen while you skate. Play It Again Sports in Greenfield is the go-to retail shop for used skates and sharpening on the south side; Hockey Haven in Brookfield is cited by local guides, though its old web domain is now for sale, so call ahead."}, {"name": "Rental sizing and skate helpers", "where": "Rinks with rentals", "badge": "Season-long", "dates": "Season-long", "price": "Rentals: Slice of Ice $11/$9; Pettit $5 (6T–15); Wilson $3.75; Eble/Naga-Waukee $3 (youth 7–adult 15); Mullett $5; Konkel & Center Street free. Helpers: Red Arrow $1 + $5 deposit; Pettit $5; Konkel free; Eble/Naga-Waukee none.", "url": "https://thepettit.com/public-skating/", "tip": "Toddler sizes are scarce at free rinks; the Pettit's 6T minimum is the smallest dependable rental.", "source": "https://urbanmilwaukee.com/pressrelease/milwaukee-county-parks-opens-slice-of-ice-at-red-arrow-park-for-2025-26-season/", "description": "Rental skates generally fit a half-size to a size smaller than street shoes; ask for figure skates for first-timers (toe pick, more stable) and hockey skates for speed. Skate helpers (walker-style frames) are first come, first served everywhere and run out on weekend afternoons."}, {"name": "Best times to avoid crowds", "where": "All rinks", "badge": "Season-long", "dates": "Season-long", "url": "https://county.milwaukee.gov/EN/Parks/Experiences/In-the-Snow", "tip": "At Slice of Ice, skate before 2 p.m. on weekdays only if you own skates — the rental window opens at 2 p.m. Mon–Fri in Jan–Feb.", "source": "https://urbanmilwaukee.com/pressrelease/milwaukee-county-parks-opens-slice-of-ice-at-red-arrow-park-for-2025-26-season/", "description": "Slice of Ice is busiest Fri–Sat nights and the Dec 26–Jan 3 holiday week (open 10 a.m.–11 p.m. in past seasons); weekday midday in January is near-empty. Indoor rinks cluster public skate at weekday noon (Eble, Naga-Waukee, Wilson) and weeknight 7 p.m. (Pettit), which are far calmer than the single Saturday sessions."}, {"name": "Free skating options", "where": "Milwaukee County & suburbs", "badge": null, "dates": "Weather dependent (except Slice of Ice, refrigerated)", "price": "Free", "url": "https://www.ci.greenfield.wi.us/862/Ice-Skating", "tip": "A used pair from Play It Again Sports pays for itself in two or three rental visits.", "source": "https://mkecoparks.helpscoutdocs.com/article/253-where-can-i-go-ice-skating-in-the-parks", "description": "Admission is free at Slice of Ice if you bring skates, and free with free loaner skates at Konkel Park (Greenfield) and Center Street Park. Every county-listed community rink (Humboldt, Lake Park, Washington Park, Hales Corners, Scout Lake, Sheridan) and the village rinks in Fox Point, Whitefish Bay, Shorewood and Waukesha are free, BYO skates. Slice of Ice's opening day traditionally includes free rentals for a few hours."}, {"name": "Ice safety and weather status", "where": "Outdoor rinks", "badge": "Season-long", "dates": "Season-long", "url": "https://county.milwaukee.gov/EN/Parks/Experiences/In-the-Snow", "tip": "Never skate a lagoon that isn't posted open, even if others are on it; the county does not test ice outside maintained areas.", "source": "https://mkecoparks.helpscoutdocs.com/article/253-where-can-i-go-ice-skating-in-the-parks", "description": "Milwaukee County requires 6 inches of ice before lagoon rinks open and posts 'Thin Ice' signs; Oconomowoc's Fowler Lake uses 7 inches. Status lines: Konkel Park 414-297-9008 (24-hr), Lake Park Friends 414-962-1680, Waukesha parks 262-522-9356, Muskego 262-679-5645; Humboldt and Center Street post on their websites/Facebook. Most natural rinks closed between Feb 9 and Feb 19 in 2026 after a warm spell."}, {"name": "Accessibility", "where": "Pettit, Red Arrow Park, Wilson, Brown Deer", "badge": "Season-long", "dates": "Season-long", "price": "Free ice sleds at Pettit, Slice of Ice and Wilson; skating aids on request at Brown Deer", "url": "https://thepettit.com/public-skating/", "tip": "At Slice of Ice, the warming house and Biggby Coffee are at ground level next to the ice; parking garages on Water St. and Kilbourn are the closest step-free options.", "source": "https://www.northshorefamilyadventures.com/winter-guides/milwaukee-ice-rinks-and-ice-skating", "description": "Refrigerated and indoor rinks are the accessible choices: level approaches, warming houses, restrooms and free adaptive sleds. Natural lagoon and pond rinks have no facilities and uneven, snowy approaches."}, {"name": "Where to warm up and eat near Red Arrow Park", "where": "Downtown / East Town", "badge": "Slice of Ice season", "dates": "Slice of Ice season", "address": "920 N. Water St. and surrounding blocks", "url": "https://county.milwaukee.gov/EN/Parks/Experiences/In-the-Snow", "tip": "The Hop streetcar's City Hall stop is one block away — ride free and skip the garage.", "source": "https://www.wisn.com/article/milwaukee-red-arrow-park-slice-of-ice-opening-hours-rentals/46285122", "description": "The warming house has a fireplace and sells hot chocolate, coffee and snacks, and Biggby Coffee operates in the former Starbucks space at the park (Starbucks closed at the end of 2022). The rink sits within two blocks of the Pfister Hotel, the Milwaukee Repertory Theater and the East Town restaurant row along Water and Milwaukee streets, and a few minutes' walk from the Deer District.", "lat": 43.0418, "lng": -87.9103}] },
];

const MAP_CATEGORIES = {"downtown": {"label": "Downtown & Signature Rinks", "color": "#0B77BD"}, "county-parks": {"label": "County Park Rinks & Wilson Park", "color": "#1F7A4D"}, "suburbs": {"label": "Suburban & Municipal Rinks", "color": "#6C3483"}, "lessons-curling": {"label": "Lessons, Hockey & Curling", "color": "#D06828"}};
const MAP_EXCLUDE = ["tips"];

const timeline = [{"period": "November 2026", "items": ["Indoor rinks in full swing: Pettit public skate Nov 3–6 and ongoing ($10 adults); Eble and Naga-Waukee weekday noon sessions ($7).", "Pettit Skating School Session 2 classes start as early as Nov 3; Eble adult intro class runs Tuesdays Nov 10–Dec 8.", "Slice of Ice 2026–27 opening date not yet announced; county says it typically opens Thanksgiving weekend–first week of December (opened Dec 13 in 2024, Dec 19 in 2025).", "Brown Deer's tent rink opened in late November last season."]}, {"period": "December 2026", "items": ["Slice of Ice expected to open; watch for the opening-day free-rental window (3–6 p.m. in 2025).", "Past December hours at Slice of Ice: Sun–Thu 11 a.m.–9 p.m., Fri–Sat 11 a.m.–11 p.m.; Dec 24 11 a.m.–6 p.m.; Dec 25 4–11 p.m.; Dec 26–Jan 3 10 a.m.–11 p.m. (incl. New Year's Eve).", "Indoor arenas add winter-break public skate sessions (Wilson, Eble, Mullett).", "Natural rinks (Humboldt, Lake Park, Konkel, Fox Point, Klode) open only after a sustained hard freeze; late December is the usual first opening."]}, {"period": "January–early February 2027 (peak)", "items": ["Best odds for natural ice at all county and village rinks; 6-inch lagoon rule in effect.", "Slice of Ice Jan–Feb hours (past seasons): Sun 11–6, Mon–Thu 11–8, Fri–Sat 11–10; rentals from 2 p.m. weekdays.", "Wauwatosa Curling Club Adaptive Open Bonspiel Jan 23–24, 2027; Shorewood Chill festival at Lake Bluff rink in early February."]}, {"period": "Mid-February–March 2027", "items": ["Natural rinks close with the first thaw (in 2026 most closed Feb 9–19); Fox Point closed Feb 10, Slice of Ice Feb 19, Center Street by Mar 1.", "Slice of Ice runs through February, into March only if weather allows.", "Wauwatosa Curling Club Valentine Open Feb 12–14, 2027; indoor rinks continue year-round."]}];
// Darkened brand shades so each heading meets 4.5:1 contrast on white.
const TIMELINE_COLORS = ["#547F4B", "#AB5521", "#0B77BD", "#83693E", "#6C3483"];

const faqs = [{"question": "Is Slice of Ice at Red Arrow Park free?", "answer": "Yes — admission is free if you bring your own skates. You only pay for rentals ($11 adults, $9 youth 17 and under in 2025–26), skate helpers ($1 plus a refundable $5 deposit) or sharpening ($7). 2026–27 rates have not been posted yet."}, {"question": "When does Red Arrow Park ice skating open for 2026?", "answer": "Milwaukee County Parks had not announced the 2026–27 opening date as of Nov 2, 2026. The county says the rink typically opens around Thanksgiving weekend or the first week of December; it opened Dec 19 in 2025 and Dec 13 in 2024 (and as late as Jan 5 in the warm winter of 2024). Check the county parks site or social media for the announcement."}, {"question": "How much are skate rentals at Red Arrow Park?", "answer": "In the 2025–26 season rentals were $11 for adults and $9 for youth 17 and under, with $5 rentals for pre-scheduled school and non-profit groups. Opening day included free rentals from 3–6 p.m. Expect similar pricing for 2026–27, pending the county's announcement."}, {"question": "Can you ice skate at the Pettit Center?", "answer": "Yes. The Pettit National Ice Center holds public skating on its 400-meter Olympic Oval, mostly weeknight evenings (around 7–9 p.m.) plus some daytime and Friday-night sessions. Admission is $10 adults, $9 seniors and teens, $8 youth 4–12, free for 3 and under; skate rental is $5. Check thepettit.com/public-skating because times shift around training and events."}, {"question": "Where can I ice skate outdoors in Milwaukee?", "answer": "Slice of Ice at Red Arrow Park is the refrigerated downtown rink. Weather-dependent natural rinks on Milwaukee County's official list include Humboldt Park Lagoon, Lake Park, Center Street Park, Washington Park Lagoon, Hales Corners Park, Scout Lake and Sheridan Park. Nearby suburbs add Konkel Park (Greenfield), Longacre Park (Fox Point), Klode Park (Whitefish Bay), Lake Bluff (Shorewood) and Brown Deer's covered rink."}, {"question": "Does Milwaukee County Parks still flood outdoor rinks?", "answer": "Not directly. The county operates Slice of Ice (refrigerated) and the indoor Wilson Ice Arena, but its outdoor lagoon and land rinks are now maintained by third parties — park Friends groups, the Urban Ecology Center and volunteers — once county staff confirm at least 6 inches of ice. The county's list currently names seven such sites; contact each group for conditions."}, {"question": "Where can kids learn to skate in Milwaukee?", "answer": "The Pettit Skating School (Learn to Skate USA, $99 per session; fall classes started Nov 3, 2026) is the largest program. Milwaukee County's Wilson Ice Arena, Waukesha County's Eble and Naga-Waukee arenas, and Hartland's Mullett Ice Center also run Learn to Skate classes, and Eble hosts an adult/senior intro class Tuesdays Nov 10–Dec 8, 2026."}, {"question": "Is there ice skating in the Deer District?", "answer": "No. There is no public rink in the Deer District or on the Fiserv Forum plaza for 2026–27; the plaza's winter programming is a holiday market. The closest ice is Slice of Ice at Red Arrow Park, about a 10-minute walk east on Kilbourn Avenue."}, {"question": "What are the cheapest indoor rinks near Milwaukee?", "answer": "Wilson Ice Arena ($6.75 adults, $5 juniors/seniors, $3.75 rental) on Milwaukee's south side and Waukesha County's Eble (Brookfield) and Naga-Waukee (Delafield) arenas ($7, $6 seniors/military, $3 rental). All three concentrate public skate at weekday noon with one weekend session."}, {"question": "Where can I try curling in Milwaukee?", "answer": "The Milwaukee Curling Club in Cedarburg (founded 1845) runs $40 Learn to Curl sessions — the fall 2026 dates were Oct 2–4, with more added through the season and a Sunday-evening new-member league. The Wauwatosa Curling Club at Hart Park holds public 'Try Curling' nights on multiple dates and hosts an Adaptive Open Bonspiel Jan 23–24, 2027."}];

